<script>(function(){function format(value){var match=String(value||'').trim().match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);if(!match)return value;var hour=parseInt(match[1],10),suffix=hour>=12?'PM':'AM';hour=hour%12||12;return String(hour).padStart(2,'0')+':'+match[2]+' '+suffix;}document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.crm-change-box div').forEach(function(row){var label=row.querySelector('b'),value=row.querySelector('span');if(label&&value&&/follow up time/i.test(label.textContent)){value.textContent=format(value.textContent);}});});}());</script>
